#include <stdint.h>

namespace loomx {

constexpr unsigned kDmxChannelsPerUniverse = 512;
constexpr unsigned kRgbLedsPerUniverse = 170;
constexpr unsigned kRgbwLedsPerUniverse = 128;

struct DmxLayout {
  unsigned channelsPerLed;      // 3 (RGB/DRGB) or 4 (RGBW)
  unsigned ledsPerUniverse;     // whole pixels in every universe after the first
  unsigned ledsInFirstUniverse; // whole pixels in the first universe
  unsigned dimmerOffset;        // 1 when the first slot is a master dimmer (DRGB)
};

// dmxAddress is WLED's DMXAddress (1..510; 0 is the legacy "start at 0").
inline DmxLayout dmxLayout(bool rgbw, bool dimmer, unsigned dmxAddress) {
  DmxLayout layout;
  layout.channelsPerLed = rgbw ? 4 : 3;
  layout.ledsPerUniverse = rgbw ? kRgbwLedsPerUniverse : kRgbLedsPerUniverse;
  layout.dimmerOffset = dimmer ? 1 : 0;
  const unsigned dmxLenOffset = (dmxAddress == 0) ? 0 : 1;
  const unsigned room = (kDmxChannelsPerUniverse - dmxAddress) + dmxLenOffset;
  layout.ledsInFirstUniverse = room > layout.dimmerOffset
      ? (room - layout.dimmerOffset) / layout.channelsPerLed : 0;
  return layout;
}

// LEDs addressed by all universes before universe offset previousUniverses.
inline unsigned previousLeds(const DmxLayout& layout, unsigned previousUniverses) {
  if (previousUniverses == 0) return 0;
  return layout.ledsInFirstUniverse + (previousUniverses - 1) * layout.ledsPerUniverse;
}

struct DmxAddress {
  unsigned universe; // absolute universe number
  unsigned channel;  // 1-based DMX slot of the pixel's first colour channel
};

// Universe and DMX channel of a pixel (0-based index into the whole strip).
inline DmxAddress pixelAddress(const DmxLayout& layout, unsigned startUniverse,
                               unsigned dmxAddress, unsigned pixel) {
  DmxAddress address;
  if (pixel < layout.ledsInFirstUniverse) {
    const unsigned firstSlot = (dmxAddress == 0 ? 1 : dmxAddress) + layout.dimmerOffset;
    address.universe = startUniverse;
    address.channel = firstSlot + pixel * layout.channelsPerLed;
    return address;
  }
  const unsigned rest = pixel - layout.ledsInFirstUniverse;
  address.universe = startUniverse + 1 + rest / layout.ledsPerUniverse;
  address.channel = 1 + (rest % layout.ledsPerUniverse) * layout.channelsPerLed;
  return address;
}

// Number of universes needed for totalLeds pixels (at least 1).
inline unsigned universeCount(const DmxLayout& layout, unsigned totalLeds) {
  if (totalLeds <= layout.ledsInFirstUniverse) return 1;
  const unsigned remain = totalLeds - layout.ledsInFirstUniverse;
  return 1 + (remain + layout.ledsPerUniverse - 1) / layout.ledsPerUniverse;
}

} // namespace loomx
